// Łączy dane z formularza i z webhooka w jeden format
// oraz dokłada ustawienia generowania wideo.
const SETTINGS = {
  // Ścieżka modelu w API Pollo.ai, np. 'pollo/pollo-v1-6' albo 'google/veo3-1-fast'
  polloModel: 'pollo/pollo-v1-6',
  resolution: '720p',
  length: 5,            // pollo-v1-6: 5 lub 10 s; veo3-1-fast: 4, 6 lub 8 s
  aspectRatio: '9:16',
  llmModel: 'gpt-4o',  // model OpenAI, który pisze scenariusz
  language: 'polski',   // język tekstów reklamy (prompt wideo zawsze po angielsku)
};

return $input.all().map((item) => {
  const src = item.json.body ?? item.json; // webhook trzyma dane w "body"
  const pick = (...keys) => {
    for (const k of keys) {
      const v = src[k];
      if (typeof v === 'string' && v.trim() !== '') return v.trim();
    }
    return '';
  };

  const ad = {
    product: pick('Produkt', 'product'),
    description: pick('Opis produktu', 'description'),
    style: pick('Styl reklamy', 'style'),
    cta: pick('Wezwanie do działania (CTA)', 'cta'),
    imageUrl: pick('URL zdjęcia produktu (opcjonalnie)', 'imageUrl'),
  };

  if (!ad.product || !ad.description) {
    throw new Error('Brak wymaganych pól: produkt i opis produktu.');
  }
  if (ad.imageUrl && !ad.imageUrl.startsWith('https://')) {
    throw new Error('URL zdjęcia musi zaczynać się od https:// (wymóg Pollo.ai).');
  }

  return { json: { ad, settings: SETTINGS } };
});

// Buduje zapytanie do OpenAI: scenariusz reklamy + prompt do wideo.
const { ad, settings } = $input.first().json;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['hook', 'script', 'onScreenText', 'cta', 'videoPrompt'],
  properties: {
    hook: { type: 'string', description: 'Pierwsze zdanie, które zatrzymuje scrollowanie' },
    script: { type: 'string', description: 'Pełny tekst lektora / narracji' },
    onScreenText: {
      type: 'array',
      items: { type: 'string' },
      description: 'Krótkie napisy na ekranie, w kolejności',
    },
    cta: { type: 'string', description: 'Wezwanie do działania na koniec' },
    videoPrompt: {
      type: 'string',
      description: 'Prompt po angielsku dla generatora wideo, maks. 900 znaków',
    },
  },
};

const system = [
  'Jesteś copywriterem i reżyserem krótkich reklam wideo na TikTok, Instagram Reels i YouTube Shorts.',
  `Piszesz teksty w języku: ${settings.language}. Wideo jest pionowe 9:16 i trwa ${settings.length} sekund, więc scenariusz musi się zmieścić w tym czasie.`,
  'Pole videoPrompt piszesz po angielsku dla modelu tekst-na-wideo: opisz jedno spójne ujęcie (obiekt, akcję, ruch kamery, światło, nastrój),',
  'pionowy kadr, bez tekstu i napisów w obrazie, bez logo i znaków towarowych, maks. 900 znaków.',
  ad.imageUrl
    ? 'Do wideo zostanie użyte zdjęcie produktu jako pierwsza klatka, więc videoPrompt opisuje, jak ta scena ma się poruszać.'
    : '',
].filter(Boolean).join(' ');

const user = [
  `Produkt: ${ad.product}`,
  `Opis: ${ad.description}`,
  `Styl reklamy: ${ad.style || 'dowolny, dopasuj do produktu'}`,
  `Wezwanie do działania: ${ad.cta || 'zaproponuj'}`,
].join('\n');

return [{
  json: {
    ad,
    settings,
    llmRequest: {
      model: settings.llmModel,
      max_tokens: 4000,
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'ad_script', strict: true, schema },
      },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
}];

// Odczytuje JSON od OpenAI i buduje zapytanie do Pollo.ai.
const res = $input.first().json;
const { ad, settings } = $('Zbuduj zapytanie do AI').first().json;

const choice = (res.choices ?? [])[0];
if (!choice) throw new Error('Brak odpowiedzi OpenAI: ' + JSON.stringify(res));
if (choice.message?.refusal) {
  throw new Error('OpenAI odmówił napisania scenariusza: ' + choice.message.refusal);
}
if (choice.finish_reason === 'length') {
  throw new Error('Odpowiedź OpenAI została ucięta (max_tokens).');
}
const scenario = JSON.parse(choice.message.content);

const input = {
  prompt: scenario.videoPrompt.slice(0, 1000),
  resolution: settings.resolution,
  length: settings.length,
};
if (ad.imageUrl) input.image = ad.imageUrl;
// Pollo 1.6 w trybie zdjęcie-na-wideo nie przyjmuje aspectRatio (bierze proporcje ze zdjęcia).
const isPolloImage = settings.polloModel.startsWith('pollo/') && ad.imageUrl;
if (!isPolloImage) input.aspectRatio = settings.aspectRatio;

return [{
  json: {
    ad,
    settings,
    scenario,
    polloUrl: 'https://pollo.ai/api/platform/generation/' + settings.polloModel,
    polloRequest: { input },
  },
}];

// Zapamiętuje taskId zwrócony przez Pollo.ai.
const res = $input.first().json;
const data = res.data ?? res; // na wypadek odpowiedzi opakowanej w "data"
if (!data.taskId) throw new Error('Pollo.ai nie zwróciło taskId: ' + JSON.stringify(res));
const prev = $('Parsuj scenariusz').first().json;
return [{ json: { ...prev, taskId: data.taskId } }];

// Sprawdza status zadania. Rzuca błąd, gdy generowanie się nie powiodło
// albo trwa zbyt długo.
const MAX_CHECKS = 60; // 60 x 20 s = 20 minut

const res = $input.first().json;
const data = res.data ?? res;
const gen = (data.generations ?? [])[0];
const status = gen?.status ?? data.status ?? 'waiting';
const task = $('Zapamiętaj taskId').first().json;
const checks = $runIndex + 1;

if (status === 'failed') {
  throw new Error('Pollo.ai: generowanie nie powiodło się. ' + (gen?.failMsg ?? ''));
}
if (status !== 'succeed' && checks >= MAX_CHECKS) {
  throw new Error(`Pollo.ai: wideo nie jest gotowe po ${checks} sprawdzeniach (taskId ${task.taskId}).`);
}

return [{
  json: {
    done: status === 'succeed',
    status,
    checks,
    taskId: task.taskId,
    videoUrl: gen?.url ?? null,
    coverUrl: gen?.cover ?? null,
    credit: data.credit ?? null,
  },
}];

// Wynik końcowy: scenariusz + link do wideo (Pollo.ai trzyma pliki do 14 dni).
const task = $('Zapamiętaj taskId').first().json;
const s = $input.first().json;
return [{
  json: {
    product: task.ad.product,
    videoUrl: s.videoUrl,
    coverUrl: s.coverUrl,
    taskId: s.taskId,
    credit: s.credit,
    hook: task.scenario.hook,
    script: task.scenario.script,
    onScreenText: task.scenario.onScreenText,
    cta: task.scenario.cta,
    videoPrompt: task.scenario.videoPrompt,
    polloModel: task.settings.polloModel,
    createdAt: new Date().toISOString(),
  },
}];
